fn max_range_nearly_can_use(champ: &Entity, target: &Entity, tick: u64) -> u64

let mut range: u64 = 0;                       // battle.rs:2398

// ── 공통 서브루틴 (전부 인라인돼 있음) ────────────────────────
// eff_range(e: &Effect) =  Effect::range(effect.rs:25~26) 인라인 결과
//     champ.stat_buff_cached.range          (Entity+0x438)
//   + e.range                               (Effect+0x10)
//   + e.growth_range * (champ.level - 1)    (Effect+0x18, Entity+0x5c8)
//   + Effect::range_adjust(e, champ, target)   ← 유일한 외부 호출(본문 미확인)
//   + radius(champ)
//   + radius(target)
//   (스테이지1·2 는 buff.range+e.range 부터, 스테이지3·4 는 growth 항부터 더한다.
//    덧셈 순서만 다르고 u64 wrapping 이라 결과는 동일)
//
// radius(x) =  Entity::radius(entity.rs:1509~1515) 인라인
//     let m = x.stat_buff_cached.radius_mult as i64;   // Entity+0x470, i32 → sext
//     if m == 0 { x.radius }                            // Entity+0x680
//     else      { (x.radius * (m + 100)) / 100 }        // udiv(부호없는 나눗셈)
//
// attack_cooldown(champ) = Entity::attack_cooldown(entity.rs:1747~1760) 인라인.
//   match champ.ty {  None(0) | Nexus(3)  => 쿨다운 필드 없음 → 게이트 자체를 건너뜀,
//     Minion(1)=>+0xb8, Tower(2)=>+0x110, Jungle(4)|Ghoul(7)=>+0xe8,
//     Epic(5)|Serpen(6)=>+0x1f0, SmallJiangshi(8)|Champion(13)=>+0xb0,
//     Bear(9)=>+0xc8, Eagle(10)=>+0xf0, Revenant(11)=>+0xd8, Illusion(12)=>+0xd0 }

// ── [1] 기본공격  battle.rs:2399~2404 ──────────────────────
if let Some(e) = champ.attack_effect.as_ref() {          // Entity+0x4c0 != -1
    if e.target.check(champ, target) {                   // CastingTarget::check
        // ★ 여기만 모든 EntityType 에 대해 쿨다운을 본다
        let skip = match champ.ty { None|Nexus => false,
                                    _ => attack_cooldown(champ) > tick };
        if !skip { range = max(range, eff_range(e)); }
    }
}

// ── [2] 스킬  battle.rs:2407~2411 ──────────────────────────
if let Some(e) = champ.skill_effect.as_ref() {           // Entity+0x4f8 != -1
    if e.target.check(champ, target) {
        // ★ ty==Champion 일 때만 쿨다운 검사. 그 외 variant 는 무조건 통과
        if !(champ.ty == Champion && champ.ty.skill_cooldown /*+0xb8*/ > tick) {
            range = max(range, eff_range(e));
        }
    }
}

// ── [3] 스킬2  battle.rs:2414~2418 ─────────────────────────
// Entity::skill2_effect()(entity.rs:1692) 인라인:
let s2: &Option<Effect> = if champ.level > 2 { &champ.skill2_effect /*+0x500*/ }
                          else { &CONST_NONE /*@anon...40 = [48B undef][i32 -1]*/ };
if let Some(e) = s2.as_ref() {
    if e.target.check(champ, target) {
        if !(champ.ty == Champion && champ.ty.skill2_cooldown /*+0xc0*/ > tick) {
            range = max(range, eff_range(e));
        }
    }
}

// ── [4] 궁극기  battle.rs:2421~2425 ────────────────────────
let ul: &Option<Effect> = if champ.level > 4 { &champ.ult_effect /*+0x538*/ }
                          else { &CONST_NONE };
if let Some(e) = ul.as_ref() {
    if e.target.check(champ, target) {
        if !(champ.ty == Champion && champ.ty.ult_cooldown /*+0xc8*/ > tick) {
            range = max(range, eff_range(e));
        }
    }
}

return range;                                             // battle.rs:2429

// 비고
// * max 는 core::cmp::Ord::max<u64>(cmp.rs:1034/1039) 인라인 → llvm.umax.i64.
//   스테이지1 은 range 가 아직 0 이라 max 가 상수접힘돼 IR 에 umax 가 3개만 남았다
//   (본문 dbg_value !56309 의 self=0 이 그 흔적).
// * 스테이지가 '스킵'돼도 range 는 유지된다(각 스킵 경로가 이전 누적값 phi 로 흘러감).
// * 4개 스테이지의 판정 순서는 고정: 공격 → 스킬 → 스킬2 → 궁. 다만 결과는 max 라
//   순서가 값에 영향을 주지 않는다(부작용 없음).
